pub fn ensureEmptyDir(path: String) -> Result<(), rt::TsonicError> {
    if !crate::fs::dirExists(&path)? {
        crate::fs::ensureDir(&path)?;
        return Ok(());
    }
    crate::fs::rejectFilesystemLink(path.clone())?;
    if !tsonic_rust_node::fs::readdir_sync(path.as_str())?.is_empty() {
        return Err(rt::TsonicError::TsumoError(
            crate::diagnostics::createTsumoError(
                String::from("TSUMO_SCAFFOLD_DESTINATION_NOT_EMPTY"),
                format!("{}{}", String::from("Directory not empty: "), path),
                Some(path.clone()),
                None,
                None,
            )?,
        ));
    }
    Ok(())
}

